function validate([matrix, k]) {
  const n = matrix.length;
  if (n < 1 || n > 300) return 'matrix needs 1 to 300 rows.';
  for (const row of matrix) {
    if (!Array.isArray(row) || row.length !== n) return 'matrix must be square (n rows of n values).';
    if (row.some(v => !Number.isInteger(v) || v < -1e9 || v > 1e9)) return 'Each value is an integer between -10^9 and 10^9.';
  }
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (j > 0 && matrix[i][j] < matrix[i][j - 1]) return 'Every row must be sorted in non-decreasing order.';
      if (i > 0 && matrix[i][j] < matrix[i - 1][j]) return 'Every column must be sorted in non-decreasing order.';
    }
  }
  if (!Number.isInteger(k) || k < 1 || k > n * n) return 'k is between 1 and n^2.';
  return null;
}

