function kthSmallest(matrix, k) {
  const n = matrix.length;
  let low = matrix[0][0];
  let high = matrix[n - 1][n - 1];

  while (low < high) {
    const mid = low + Math.floor((high - low) / 2);
    let count = 0;
    let col = n - 1;
    for (let row = 0; row < n; row++) {
      while (col >= 0 && matrix[row][col] > mid) {
        col--;
      }
      count += col + 1;
    }
    if (count < k) {
      low = mid + 1;
    } else {
      high = mid;
    }
  }
  return low;
}

