function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 5);
  const step = size === 'large' ? 1 + Math.floor(rand() * 10000000) : 1 + Math.floor(rand() * 4);
  const start = size === 'large' ? -1000000000 + Math.floor(rand() * 1000) : Math.floor(rand() * 11) - 5;
  const matrix = [];
  for (let i = 0; i < n; i++) {
    const row = [];
    for (let j = 0; j < n; j++) {
      const above = i > 0 ? matrix[i - 1][j] : -Infinity;
      const before = j > 0 ? row[j - 1] : -Infinity;
      const floor = i === 0 && j === 0 ? start : Math.max(above, before);
      row.push(floor + Math.floor(rand() * step));
    }
    matrix.push(row);
  }
  const k = 1 + Math.floor(rand() * n * n);
  return [matrix, k];
}
